    "segments": [
      {
        "start": 0,
        "duration": 10.29,
        "text": "Hallo zusammen, willkommen zurück bei Bright Circuits."
      },
      {
        "start": 10.5,
        "duration": 10.29,
        "text": "Heute beantworten wir eine Frage, die ich"
      },
      {
        "start": 21,
        "duration": 10.29,
        "text": "ständig bekomme: Wie verwandelt eine flache Glasscheibe"
      },
      {
        "start": 31.5,
        "duration": 10.29,
        "text": "auf dem Dach Sonnenlicht in nutzbaren Strom?"
      },
      {
        "start": 42,
        "duration": 25.48,
        "text": "Beginnen wir mit dem Sonnenlicht selbst. Licht"
      },
      {
